import{_ as n,l as o,o as e,c as l,v as t,p as E,x as r,d,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"重复博弈与无名氏定理","description":"","frontmatter":{"title":"重复博弈与无名氏定理","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/folk-theorem.md","filePath":"econ/folk-theorem.md","lastUpdated":1789023840000}'),m={name:"econ/folk-theorem.md"};function c(h,a,A,B,P,u){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="重复博弈与无名氏定理" tabindex="-1">重复博弈与无名氏定理 <a class="header-anchor" href="#重复博弈与无名氏定理" aria-label="Permalink to &quot;重复博弈与无名氏定理&quot;">​</a></h1><div class="epigraph"><p>贴现足够耐心时，任何可行且个人理性的支付，都可以由子博弈完美均衡支撑。</p><footer>—— 据 Friedman, Review of Economic Studies, 1971；Fudenberg and Maskin, Econometrica, 1986 整理</footer></div><p><a href="/econ/backward-induction-limits">上一课</a>（逆向归纳的限度）。用 SPE 删掉一次性树上的空威胁。把同一阶段博弈重复下去，惩罚变成「以后改玩另一条路径」，而路径本身可以是均衡。缺口是：SPE 在重复结构里不再瘦，反而极肥。无名氏定理给出肥到什么程度。本课钉可支撑支付的集合，不引入类型与贝叶斯。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>阶段博弈的纳什支付记为 \\(e\\)，可行支付集 \\(V\\) 是阶段支付的凸组合（可公随机化）。个人理性水平 \\(v_i\\) 是别人能把 \\(i\\) 压到的最低（minimax）。一次性囚徒困境里，SPE（也是纳什）只有招供；合作支付在 \\(V\\) 里，但高于 \\(e\\)，一次性不可信。</p><p>重复之后，偏离的人可以被转到 minimax 或转到「惩罚纳什」。若贴现因子 \\(\\delta\\) 够大，未来损失压过当期偏离增益，合作路径可以是 SPE。Friedman 的纳什回归已经能撑住严格优于 \\(e\\) 的点；Fudenberg–Maskin 在有限行动、可观察混合的条件下，把集合扩到几乎整个可行且个人理性的集合。</p><h3 id="无名氏不是「合作必然出现」" tabindex="-1">无名氏不是「合作必然出现」 <a class="header-anchor" href="#无名氏不是「合作必然出现」" aria-label="Permalink to &quot;无名氏不是「合作必然出现」&quot;">​</a></h3><p>定理是可能性：许多支付都有某个 SPE 去实现。它不选哪一个。贴现、监测、是否公开随机化，决定能撑住多大一块。把无名氏读成「重复就能卡特尔」，漏掉了均衡选择与监测。</p><p><span class="marginnote">触发策略：路径上合作，一旦观测到偏离，永远回到阶段纳什。这是 SPE，因为惩罚子博弈本身是纳什的重复，惩罚者愿意执行。minimax 惩罚更狠，但惩罚者可能需要自己也受苦，可信性要靠互罚或统计触发。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：完全信息、完美监测、同一阶段无限重复，共同贴现 \\(\\delta\\)。结论（教科书版）：存在 \\(\\underline{\\delta}\\lt 1\\)，对一切 \\(\\delta\\gt \\underline{\\delta}\\)，任何可行且严格个人理性的支付向量，是某个 SPE 的平均支付。有限重复若阶段纳什唯一，逆向归纳仍钉在 \\(e\\) 上；阶段有多个纳什时，有限次也能用「最后几期的纳什奖励」撑住前期合作。</p><p>公开监测是关键。若只能看见噪声信号，绿光–红光（Green–Porter）一类均衡用统计触发，效率有损耗。本课主钉完美监测，作为上界。</p>',12)),(e(),E(p,null,{default:r(()=>[s(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAGE%5B%22%E9%98%B6%E6%AE%B5%E7%BA%B3%E4%BB%80%20e%22%5D%20--%3E%20REP%5B%22%E6%97%A0%E9%99%90%E9%87%8D%E5%A4%8D%22%5D%0A%20%20REP%20--%3E%20FOLK%5B%22%CE%B4%20%E5%A4%A7%EF%BC%9AV%20%E4%B8%AD%E4%B8%AA%E4%BA%BA%E7%90%86%E6%80%A7%E7%82%B9%E7%9A%86%E5%8F%AF%20SPE%22%5D%0A%20%20FOLK%20--%3E%20SEL%5B%22%E4%B8%8D%E9%80%89%E5%93%AA%E4%B8%80%E4%B8%AA%E5%9D%87%E8%A1%A1%22%5D%0A%20%20REP%20--%3E%20IMP%5B%22%E7%9B%91%E6%B5%8B%E5%B7%AE%EF%BC%9A%E9%9B%86%E5%90%88%E5%86%8D%E6%94%B6%E7%BC%A9%22%5D%0A%20%20FOLK%20--%3E%20BAYES%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%B1%BB%E5%9E%8B%E6%9C%AA%E7%9F%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>贴现把未来折成当期可比较的损失。SPE 要求惩罚子博弈里人人仍最优：所以惩罚必须本身是均衡路径，不能是「对自己也更糟且到达后不愿做」的一次性疯价。重复提供了这类均衡路径的库存——至少阶段纳什的重复永远可用。这正是上一课「空威胁删掉」之后，结构本身又把可信惩罚生产出来。</p><p>人数与可观察性决定联盟能否维持。公共品重复提供，仍要看见谁没出钱。秘密削价使监测变成统计推断，无名氏的肥集合变瘦。这与<a href="/econ/coase-theorem">科斯</a>小数目、Olson 小集团是同一经验：重复帮得上忙，但不是无限忙。均衡选择仍空着：合作是一个 SPE，永远玩阶段纳什也是 SPE。定理不帮你挑。要靠类型、声誉把集合再切一刀，必须进入不完全信息。</p><h3 id="有限重复从尾部拆掉" tabindex="-1">有限重复从尾部拆掉 <a class="header-anchor" href="#有限重复从尾部拆掉" aria-label="Permalink to &quot;有限重复从尾部拆掉&quot;">​</a></h3><p>阶段纳什唯一时，最后一期没有未来可罚，逆向归纳钉在 \\(e\\) 上，合作从尾部解开。未知结束日期、或每期以正概率继续，才接近无限重复。阶段有多个纳什时，有限次也能用「最后几期选好的那个纳什」当奖励。 \\(\\delta\\) 低只剩阶段纳什； \\(\\delta\\) 高则几乎任何不低于 minimax 的分赃都能被撑住。</p><p><span class="marginnote">粗算：一期投机所得 \\(\\Delta\\) 必须小于 \\(\\frac{\\delta}{1-\\delta}\\) 乘上惩罚造成的每期损失。 \\(\\delta\\) 的下限由 \\(\\Delta\\) 与惩罚深度决定。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不完全监测、私人监测、重新谈判（punishment 被再谈掉）都会改写定理。有限重复加唯一阶段纳什，合作崩回 \\(e\\)。不完全信息（声誉）可以在有限次里撑住合作，那是类型，下一课。</p><p>也不要把无名氏写成宏观政策的承诺技术；承诺与时间不一致是后课程的另套结构。本课只说：SPE 在重复下失去「几乎唯一」的筛选力。</p><p>可公随机化把阶段支付集做成凸集；没有它，能撑住的点少一块，定理的陈述要改成「凸包里的点」。</p><p>后课默认：完全信息重复博弈的 SPE 支付，在耐心与完美监测下接近可行个人理性集；要缩小，需信息不完全或精炼。</p><p>阶段纳什唯一时，有限重复从最后一期往前拆掉合作。无限次才把「还有下一期」写进贴现和。有限次里要看见合作，必须多个阶段纳什，或进入类型。Green–Porter 一类不完美监测用统计触发，均衡路径上也会惩罚，效率有损耗；完美监测是本课给出的上界。重新谈判若能在惩罚时把惩罚再谈掉，无名氏集合再切一刀。</p><p><span class="marginnote">可公随机化把阶段支付集做成凸集；没有它，能撑住的点少一块。不要把无名氏写成限价簿上用未来订单「惩罚」对手的微观结构。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一次性 SPE 可能很瘦；重复后 SPE 支付集可以几乎填满可行且个人理性集。</li><li>惩罚必须自身是均衡，贴现要压过偏离增益。</li><li>定理给可能性，不给选择。</li><li>监测与有限地平线会把集合切回去。</li><li>出处：Friedman, <em>RES</em> 1971；Fudenberg and Maskin, <em>Econometrica</em> 1986。</li></ul>',15))])}const f=n(m,[["render",c]]);export{S as __pageData,f as default};
